actions.action:
// Limit interest deduction to 30% of ATI
// Excess carried forward (not implemented in Phase 1)
result.interest_expense = 0.30 * result.taxable_income;

// Limit charitable contributions to 10% of taxable income
// Excess carried forward 5 years (not implemented in Phase 1)
result.charitable_contributions = 0.10 * result.taxable_income;

// Total payments includes estimated payments + prior year overpayment credits
result.total_payments = result.estimated_tax_payments + result.total_credits;

// Refund (positive) or owed (negative)
result.refund_or_owed = result.total_payments - result.federal_tax;

// R&D credit calculation (simplified for Phase 2)
// Full implementation requires base period calculations
// Phase 2: Accept pre-calculated credit amount

// Sum all business credits
result.general_business_credit =
  result.research_development_credit +
  result.work_opportunity_credit;

// Apply to total credits
result.total_credits = result.general_business_credit;

set asset.asset_class = "7-year";
set asset.recovery_period = 7;
set asset.depreciation_method = "MACRS-200DB";

set asset.section_179_deduction = asset.cost_basis;
add asset.cost_basis to result.section_179_total;
set asset.cost_basis = 0.0;

set asset.bonus_depreciation = asset.cost_basis * result.bonus_depreciation_rate;
add (asset.cost_basis * result.bonus_depreciation_rate) to result.bonus_depreciation_total;
set asset.cost_basis = asset.cost_basis - asset.bonus_depreciation;

set asset.current_year_depreciation = asset.cost_basis * 0.1429;
add asset.current_year_depreciation to asset.accumulated_depreciation;
add asset.current_year_depreciation to result.macrs_depreciation_total;

// Total depreciation = Section 179 + Bonus + MACRS
result.depreciation =
  result.section_179_total +
  result.bonus_depreciation_total +
  result.macrs_depreciation_total;

// Calculate average property (beginning + ending) / 2
apportionment.property_average =
  (apportionment.property_beginning_balance + apportionment.property_ending_balance) / 2.0;

// Calculate property factor
apportionment.property_factor =
  apportionment.property_average / apportionment.property_total_average;

// Calculate payroll factor
apportionment.payroll_factor =
  apportionment.payroll_in_state / apportionment.payroll_total;

// Calculate sales factor
apportionment.sales_factor =
  apportionment.sales_in_state / apportionment.sales_total;

// Three-factor formula: (P + Pa + S) / 3
apportionment.apportionment_percentage =
  (apportionment.property_factor +
   apportionment.payroll_factor +
   apportionment.sales_factor) / 3.0;

// Double-weighted sales: (P + Pa + 2×S) / 4
apportionment.apportionment_percentage =
  (apportionment.property_factor +
   apportionment.payroll_factor +
   (2.0 * apportionment.sales_factor)) / 4.0;

set apportionment.apportioned_income = result.taxable_income * apportionment.apportionment_percentage;
set apportionment.state_taxable_income = apportionment.apportioned_income + apportionment.state_additions - apportionment.state_subtractions;
set apportionment.state_tax = apportionment.state_taxable_income * apportionment.state_tax_rate;
set apportionment.state_tax = apportionment.state_tax - apportionment.state_credits;
set apportionment.state_refund_or_owed = apportionment.state_payments - apportionment.state_tax;
